import{_ as n,c as s,o as t,ag as e}from"./chunks/framework.CMajxlqO.js";const u=JSON.parse('{"title":"Skärmbilder och HMI-layout","description":"","frontmatter":{},"headers":[],"relativePath":"07-hmi-design/skarmbilder.md","filePath":"07-hmi-design/skarmbilder.md","lastUpdated":1768462574000}'),r={name:"07-hmi-design/skarmbilder.md"};function i(o,a,l,p,d,c){return t(),s("div",null,[...a[0]||(a[0]=[e(`<h1 id="skarmbilder-och-hmi-layout" tabindex="-1">Skärmbilder och HMI-layout <a class="header-anchor" href="#skarmbilder-och-hmi-layout" aria-label="Permalink to &quot;Skärmbilder och HMI-layout&quot;">​</a></h1><p>HMI-skärmar (screens) är operatörens fönster till automationssystemet. I TIA Portal skapar du intuitivé, funktionella skärmar med WinCC (Windows Control Center) - HMI-redigeraren.</p><h2 id="oversikt-wincc-i-tia-portal" tabindex="-1">Översikt: WinCC i TIA Portal <a class="header-anchor" href="#oversikt-wincc-i-tia-portal" aria-label="Permalink to &quot;Översikt: WinCC i TIA Portal&quot;">​</a></h2><p><strong>WinCC</strong> är Siemens HMI-mjukvara, integrerad i TIA Portal för:</p><ul><li>📺 <strong>HMI-paneler</strong> (KTP, TP, MP-serien)</li><li>💻 <strong>PC-baserade HMI</strong> (WinCC Runtime Advanced/Professional)</li><li>📱 <strong>Web-baserade HMI</strong> (WinCC Unified)</li></ul><h3 id="hmi-projekt-struktur" tabindex="-1">HMI-projekt-struktur <a class="header-anchor" href="#hmi-projekt-struktur" aria-label="Permalink to &quot;HMI-projekt-struktur&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HMI_1 [KTP700 Basic]</span></span>
<span class="line"><span>├── Screens</span></span>
<span class="line"><span>│   ├── Root screen (Startskärm)</span></span>
<span class="line"><span>│   ├── Overview (Översikt)</span></span>
<span class="line"><span>│   ├── Motor_Control</span></span>
<span class="line"><span>│   ├── Alarms</span></span>
<span class="line"><span>│   └── Settings</span></span>
<span class="line"><span>├── HMI tags</span></span>
<span class="line"><span>├── Connections (till PLC)</span></span>
<span class="line"><span>└── Alarms</span></span></code></pre></div><h2 id="skapa-ny-skarm" tabindex="-1">Skapa ny skärm <a class="header-anchor" href="#skapa-ny-skarm" aria-label="Permalink to &quot;Skapa ny skärm&quot;">​</a></h2><h3 id="steg-for-steg" tabindex="-1">Steg-för-steg <a class="header-anchor" href="#steg-for-steg" aria-label="Permalink to &quot;Steg-för-steg&quot;">​</a></h3><ol><li><p><strong>Öppna HMI-projektet</strong></p><ul><li>I Project tree: HMI_1 → <strong>Screens</strong></li></ul></li><li><p><strong>Lägg till ny skärm</strong></p><ul><li>Högerklicka <strong>Screens</strong> → <strong>Add new screen</strong></li><li>Namn: <code>Overview</code></li><li>Typ: <strong>Standard screen</strong> (default)</li><li>Klicka <strong>OK</strong></li></ul></li><li><p><strong>Öppna skärmen</strong></p><ul><li>Dubbelklicka <code>Overview</code> → Öppnas i WinCC editor</li></ul></li></ol><h3 id="skarm-typer" tabindex="-1">Skärm-typer <a class="header-anchor" href="#skarm-typer" aria-label="Permalink to &quot;Skärm-typer&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Typ</th><th>Användning</th><th>Storlek</th></tr></thead><tbody><tr><td><strong>Standard screen</strong></td><td>Normal processida</td><td>Hela skärmen</td></tr><tr><td><strong>Popup screen</strong></td><td>Larm, dialogrutor</td><td>Anpassningsbar (ex: 400x300)</td></tr><tr><td><strong>Slide-in screen</strong></td><td>Snabbmeny, inställningar</td><td>Delvis skärm (slide från kant)</td></tr><tr><td><strong>Template screen</strong></td><td>Återanvändbar layout</td><td>Bas för andra skärmar</td></tr></tbody></table><h2 id="skarm-layout-och-design" tabindex="-1">Skärm-layout och design <a class="header-anchor" href="#skarm-layout-och-design" aria-label="Permalink to &quot;Skärm-layout och design&quot;">​</a></h2><h3 id="rekommenderade-zoner" tabindex="-1">Rekommenderade zoner <a class="header-anchor" href="#rekommenderade-zoner" aria-label="Permalink to &quot;Rekommenderade zoner&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────┐</span></span>
<span class="line"><span>│  Header: Titel, datum, tid          │ ← 10% av skärmen</span></span>
<span class="line"><span>├─────────────────────────────────────┤</span></span>
<span class="line"><span>│                                     │</span></span>
<span class="line"><span>│  Main Area: Process-grafik          │ ← 70%</span></span>
<span class="line"><span>│  Knappar, värden, animationer       │</span></span>
<span class="line"><span>│                                     │</span></span>
<span class="line"><span>├─────────────────────────────────────┤</span></span>
<span class="line"><span>│  Footer: Navigation, larmstatus     │ ← 20%</span></span>
<span class="line"><span>└─────────────────────────────────────┘</span></span></code></pre></div><h3 id="header-sektion-exempel" tabindex="-1">Header-sektion (exempel) <a class="header-anchor" href="#header-sektion-exempel" aria-label="Permalink to &quot;Header-sektion (exempel)&quot;">​</a></h3><p><strong>Objekt:</strong></p><ul><li><strong>Text field:</strong> Skärmtitel (&quot;Motor Control&quot;)</li><li><strong>Date/Time:</strong> Systemdatum och tid</li><li><strong>Button:</strong> Hem-knapp (tillbaka till översikt)</li></ul><p><strong>Layout:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[🏠 Home]  Motor Control System       [📅 2024-01-15  🕐 14:32:15]</span></span></code></pre></div><h3 id="main-area" tabindex="-1">Main Area <a class="header-anchor" href="#main-area" aria-label="Permalink to &quot;Main Area&quot;">​</a></h3><p>Huvudområde för:</p><ul><li>Process-grafik (tankar, motorer, ventiler)</li><li>Realtidsvärden (temperatur, tryck, hastighet)</li><li>Kontrollknappar (start/stopp)</li><li>Status-indikatorer</li></ul><h3 id="footer-sektion" tabindex="-1">Footer-sektion <a class="header-anchor" href="#footer-sektion" aria-label="Permalink to &quot;Footer-sektion&quot;">​</a></h3><p><strong>Objekt:</strong></p><ul><li><strong>Navigation buttons:</strong> Länkar till andra skärmar</li><li><strong>Alarm indicator:</strong> Visar antal aktiva larm</li><li><strong>User info:</strong> Inloggad operatör</li></ul><p><strong>Layout:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Overview] [Motors] [Tanks] [Settings]    ⚠️ 2 Alarms    👤 User: Anna</span></span></code></pre></div><h2 id="navigation-mellan-skarmar" tabindex="-1">Navigation mellan skärmar <a class="header-anchor" href="#navigation-mellan-skarmar" aria-label="Permalink to &quot;Navigation mellan skärmar&quot;">​</a></h2><h3 id="metod-1-knapp-med-activatescreen" tabindex="-1">Metod 1: Knapp med &quot;ActivateScreen&quot; <a class="header-anchor" href="#metod-1-knapp-med-activatescreen" aria-label="Permalink to &quot;Metod 1: Knapp med &quot;ActivateScreen&quot;&quot;">​</a></h3><ol><li><strong>Lägg till Button</strong> på skärmen</li><li><strong>Konfigurera Events:</strong><ul><li><strong>Event:</strong> Click</li><li><strong>Function:</strong> ActivateScreen</li><li><strong>Screen name:</strong> <code>Motor_Control</code></li></ul></li></ol><p><strong>Resultat:</strong> När operatör klickar knappen, öppnas <code>Motor_Control</code>-skärmen.</p><h3 id="metod-2-navigation-bar" tabindex="-1">Metod 2: Navigation bar <a class="header-anchor" href="#metod-2-navigation-bar" aria-label="Permalink to &quot;Metod 2: Navigation bar&quot;">​</a></h3><p>Skapa en återanvändbar navigationsmeny (template).</p><p><strong>Template &quot;NavBar&quot;:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Overview] [Motors] [Tanks] [Alarms] [Settings]</span></span></code></pre></div><p><strong>Lägg till i alla skärmar:</strong></p><ol><li>Skapa template &quot;NavBar&quot;</li><li>Lägg till knappar med ActivateScreen för varje skärm</li><li>I varje skärm: <strong>Insert</strong> → <strong>Template</strong> → <code>NavBar</code></li></ol><div class="tip custom-block"><p class="custom-block-title">Template-fördel</p><p>Ändra NavBar-templaten → alla skärmar uppdateras automatiskt!</p></div><h3 id="metod-3-programmatisk-navigation-fran-plc" tabindex="-1">Metod 3: Programmatisk navigation från PLC <a class="header-anchor" href="#metod-3-programmatisk-navigation-fran-plc" aria-label="Permalink to &quot;Metod 3: Programmatisk navigation från PLC&quot;">​</a></h3><p>PLC kan tvinga HMI att byta skärm (ex: vid larm).</p><p><strong>I HMI:</strong></p><ol><li>Skapa <strong>HMI tag:</strong> <code>Screen_Number</code> (INT)</li><li>Lägg till script i <strong>Root screen:</strong></li></ol><div class="language-vbs vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vbs</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&#39; VB Script i Root screen (Cyclic)</span></span>
<span class="line"><span>If Tag(&quot;Screen_Number&quot;) = 1 Then</span></span>
<span class="line"><span>    ActivateScreen &quot;Overview&quot;</span></span>
<span class="line"><span>ElseIf Tag(&quot;Screen_Number&quot;) = 2 Then</span></span>
<span class="line"><span>    ActivateScreen &quot;Motor_Control&quot;</span></span>
<span class="line"><span>ElseIf Tag(&quot;Screen_Number&quot;) = 10 Then</span></span>
<span class="line"><span>    ActivateScreen &quot;Alarms&quot;</span></span>
<span class="line"><span>End If</span></span></code></pre></div><p><strong>I PLC:</strong></p><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Tvinga skärmbyte vid larm</span></span>
<span class="line"><span>IF &quot;Alarm_Critical&quot; THEN</span></span>
<span class="line"><span>    &quot;HMI_Screen_Number&quot; := 10;</span><span>  // Öppna Alarm-skärm</span></span>
<span class="line"><span>END_IF;</span></span></code></pre></div><h2 id="organisera-skarmar" tabindex="-1">Organisera skärmar <a class="header-anchor" href="#organisera-skarmar" aria-label="Permalink to &quot;Organisera skärmar&quot;">​</a></h2><h3 id="anvand-mappar" tabindex="-1">Använd mappar <a class="header-anchor" href="#anvand-mappar" aria-label="Permalink to &quot;Använd mappar&quot;">​</a></h3><p>För stora projekt, organisera skärmar i mappar.</p><p><strong>Struktur:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Screens</span></span>
<span class="line"><span>├── 00_Main</span></span>
<span class="line"><span>│   ├── Root_Screen</span></span>
<span class="line"><span>│   └── Overview</span></span>
<span class="line"><span>├── 01_Motors</span></span>
<span class="line"><span>│   ├── Motor_M01</span></span>
<span class="line"><span>│   ├── Motor_M02</span></span>
<span class="line"><span>│   └── Motor_M03</span></span>
<span class="line"><span>├── 02_Tanks</span></span>
<span class="line"><span>│   ├── Tank_T01</span></span>
<span class="line"><span>│   └── Tank_T02</span></span>
<span class="line"><span>└── 99_System</span></span>
<span class="line"><span>    ├── Alarms</span></span>
<span class="line"><span>    └── Settings</span></span></code></pre></div><p><strong>Skapa mapp:</strong></p><ol><li>Högerklicka <strong>Screens</strong> → <strong>Add new folder</strong></li><li>Namn: <code>01_Motors</code></li></ol><h3 id="namnkonvention" tabindex="-1">Namnkonvention <a class="header-anchor" href="#namnkonvention" aria-label="Permalink to &quot;Namnkonvention&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Rekommendation</p><p>Använd prefix för sortering:</p><ul><li><code>00_</code> - Huvud/root-skärmar</li><li><code>01_</code> - Process-skärmar (motorer)</li><li><code>02_</code> - Process-skärmar (tankar)</li><li><code>99_</code> - System (larm, inställningar)</li></ul></div><h2 id="popup-skarmar" tabindex="-1">Popup-skärmar <a class="header-anchor" href="#popup-skarmar" aria-label="Permalink to &quot;Popup-skärmar&quot;">​</a></h2><h3 id="nar-anvanda-popups" tabindex="-1">När använda popups <a class="header-anchor" href="#nar-anvanda-popups" aria-label="Permalink to &quot;När använda popups&quot;">​</a></h3><p>✅ <strong>Använd för:</strong></p><ul><li>Larmbekräftelse</li><li>Snabba inställningar</li><li>&quot;Är du säker?&quot;-dialoger</li><li>Detaljerad information (klicka för mer info)</li></ul><p>❌ <strong>Använd INTE för:</strong></p><ul><li>Huvudprocess-vyer</li><li>Navigation (använd standard screens)</li></ul><h3 id="skapa-popup" tabindex="-1">Skapa popup <a class="header-anchor" href="#skapa-popup" aria-label="Permalink to &quot;Skapa popup&quot;">​</a></h3><ol><li><strong>Add new screen</strong> → Type: <strong>Popup screen</strong></li><li>Storlek: 400x300 px (anpassas efter behov)</li><li><strong>Properties:</strong><ul><li><strong>Title bar:</strong> Visa/dölj</li><li><strong>Close button:</strong> Tillåt stängning</li><li><strong>Modal:</strong> Blockera bakgrund (ja/nej)</li></ul></li></ol><h3 id="oppna-popup-fran-knapp" tabindex="-1">Öppna popup från knapp <a class="header-anchor" href="#oppna-popup-fran-knapp" aria-label="Permalink to &quot;Öppna popup från knapp&quot;">​</a></h3><p><strong>Event:</strong></p><ul><li>Event: Click</li><li>Function: <strong>ShowPopupScreen</strong></li><li>Screen: <code>Popup_MotorSettings</code></li><li>Position: Center</li></ul><h2 id="responsive-design" tabindex="-1">Responsive design <a class="header-anchor" href="#responsive-design" aria-label="Permalink to &quot;Responsive design&quot;">​</a></h2><h3 id="landskap-vs-portratt" tabindex="-1">Landskap vs Porträtt <a class="header-anchor" href="#landskap-vs-portratt" aria-label="Permalink to &quot;Landskap vs Porträtt&quot;">​</a></h3><p>Siemens HMI-paneler är oftast <strong>landskap</strong> (800x480, 1024x768), men mobila HMI kan vara <strong>porträtt</strong>.</p><p><strong>Tips:</strong></p><ul><li>Designa för målpanelens upplösning</li><li>Använd <strong>grouping</strong> för att hålla objekt tillsammans vid storleksändring</li></ul><h3 id="multi-resolution-support" tabindex="-1">Multi-resolution support <a class="header-anchor" href="#multi-resolution-support" aria-label="Permalink to &quot;Multi-resolution support&quot;">​</a></h3><p>För projekt med olika paneler (ex: KTP700 + TP1200):</p><ol><li>Skapa <strong>separate screen folders</strong> för varje upplösning</li><li>Eller: Använd <strong>VectorGraphics</strong> som skalar automatiskt</li></ol><h2 id="best-practices" tabindex="-1">Best practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best practices&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Designrekommendationer</p><ol><li><strong>Konsistens:</strong> Samma layout, färger och typsnitt på alla skärmar</li><li><strong>Enkelhet:</strong> Max 10-15 knappar per skärm - undvik information overload</li><li><strong>Hierarki:</strong> Overview → Detail - börja med översikt, gå djupare vid behov</li><li><strong>Färgkodning:</strong><ul><li>🟢 Grön: Kör/OK</li><li>🔴 Röd: Stopp/Fel</li><li>🟡 Gul: Varning</li><li>⚪ Grå: Inaktiv</li></ul></li><li><strong>Läsbarhet:</strong> Stora knappar (min 50x50 px), tydliga etiketter</li><li><strong>Navigation:</strong> Max 3 klick från översikt till valfri funktion</li><li><strong>Templates:</strong> Återanvänd header/footer för konsekvens</li><li><strong>Test:</strong> Testa på faktisk panel, inte bara i simulator</li></ol></div><h2 id="exempel-motorstyrnings-skarm" tabindex="-1">Exempel: Motorstyrnings-skärm <a class="header-anchor" href="#exempel-motorstyrnings-skarm" aria-label="Permalink to &quot;Exempel: Motorstyrnings-skärm&quot;">​</a></h2><h3 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────┐</span></span>
<span class="line"><span>│ [🏠] Motor M01 Control  📅 2024-01-15 │</span></span>
<span class="line"><span>├──────────────────────────────────────┤</span></span>
<span class="line"><span>│                                      │</span></span>
<span class="line"><span>│    🔵 Motor M01                      │</span></span>
<span class="line"><span>│    ════════════                      │</span></span>
<span class="line"><span>│                                      │</span></span>
<span class="line"><span>│    Speed: [1450] rpm                 │</span></span>
<span class="line"><span>│    Current: [12.5] A                 │</span></span>
<span class="line"><span>│    Temp: [65] °C                     │</span></span>
<span class="line"><span>│                                      │</span></span>
<span class="line"><span>│    [▶ START]  [⏹ STOP]              │</span></span>
<span class="line"><span>│                                      │</span></span>
<span class="line"><span>│    Speed setpoint: [____] rpm        │</span></span>
<span class="line"><span>│    [  slider  ]                      │</span></span>
<span class="line"><span>│                                      │</span></span>
<span class="line"><span>├──────────────────────────────────────┤</span></span>
<span class="line"><span>│ [Overview] [Motors] [Alarms]     👤  │</span></span>
<span class="line"><span>└──────────────────────────────────────┘</span></span></code></pre></div><h3 id="objekt-lista" tabindex="-1">Objekt-lista <a class="header-anchor" href="#objekt-lista" aria-label="Permalink to &quot;Objekt-lista&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Objekt</th><th>Typ</th><th>Funktion</th></tr></thead><tbody><tr><td>Motor ikon</td><td>Circle</td><td>Animation: Grön (igång), Grå (stopp)</td></tr><tr><td>Speed-värde</td><td>I/O Field</td><td>Visa <code>Motor_Speed</code> (read-only)</td></tr><tr><td>START-knapp</td><td>Button</td><td>Event: SetBit <code>Motor_Start</code></td></tr><tr><td>STOP-knapp</td><td>Button</td><td>Event: ResetBit <code>Motor_Start</code></td></tr><tr><td>Speed setpoint</td><td>I/O Field</td><td>Skriv till <code>Motor_Speed_Setpoint</code></td></tr><tr><td>Slider</td><td>Slider</td><td>Kontroll för hastighet (0-1500)</td></tr></tbody></table><h2 id="resurser" tabindex="-1">Resurser <a class="header-anchor" href="#resurser" aria-label="Permalink to &quot;Resurser&quot;">​</a></h2><ul><li><a href="https://support.industry.siemens.com/cs/document/109742856/hmi-design-best-practices" target="_blank" rel="noreferrer">Siemens: WinCC HMI Design Guide (PDF)</a></li><li><a href="https://www.youtube.com/watch?v=qZuWhPk1yQo" target="_blank" rel="noreferrer">Video: Creating HMI Screens in TIA Portal</a></li><li><a href="https://www.youtube.com/watch?v=3DtZ8n-7ycA" target="_blank" rel="noreferrer">Video: HMI Navigation and Popups</a></li><li><a href="./knappar-indikatorer.html">Nästa: Knappar och indikatorer →</a></li></ul><hr><p><strong>Relaterat:</strong></p><ul><li><a href="./../03-konfiguration/hmi-installningar.html">HMI-konfiguration</a></li><li><a href="./../05-taggar/koppling-plc-hmi.html">Koppling PLC↔HMI</a></li><li><a href="./dynamiska-objekt.html">Dynamiska objekt och animationer</a></li></ul>`,86)])])}const h=n(r,[["render",i]]);export{u as __pageData,h as default};
